<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {ArrowRight,ArrowUp,ArrowDown,Check,Plus,RefreshCw,Save,ShieldCheck,Trash2,Undo2} from 'lucide-vue-next'
import type {Account,Schedule} from '../types'
import {request} from '../api'
const props=defineProps<{accounts:Account[];demo:boolean;initialID?:string;initialMode?:string}>()
const emit=defineEmits<{refresh:[]}>()
type Task=Record<string,any>
type Fields={bool?:string[];int?:Record<string,[number,number]>;enum?:Record<string,string[]>;string?:string[];strings?:string[]}
type Op={scope:string;task?:number;plan?:number;field?:string;value?:unknown;shift?:number;room?:string;index?:number}
type Plan={id:string;account_id:string;target:string;state:string;summary:string;diff:{path:string;before:unknown;after:unknown}[];receipt:string;expires_at:string;rollback_of?:string}
const id=ref(props.initialID||props.accounts[0]?.id||''),mode=ref(props.initialMode||'tasks'),catalog=ref<{tasks:Record<string,Fields>;plan:Fields}>({tasks:{},plan:{}}),snapshot=ref<Account|null>(null)
const original=ref<Task[]>([]),tasks=ref<Task[]>([]),originalSchedule=ref<Schedule|null>(null),schedule=ref<Schedule|null>(null),timers=ref<any[]>([]),originalTimers=ref<any[]>([]),shift=ref(0)
const notifySave=ref(false)
const selectedPlan=ref<Plan|null>(null),plans=ref<Plan[]>([]),ack=ref(false),busy=ref(false),error=ref(''),message=ref(''),addFields=ref<Record<number,string>>({})
const newPlan=ref({Stage:'',DropId:'',DropCount:1}),depotIndex=ref(0)
const clone=<T,>(x:T):T=>JSON.parse(JSON.stringify(x))
const same=(a:unknown,b:unknown)=>JSON.stringify(a)===JSON.stringify(b)
const selected=computed(()=>snapshot.value||props.accounts.find(a=>a.id===id.value))
const secondary=computed(()=>selected.value?.role==='secondary')
const depotPlans=computed(()=>(tasks.value[depotIndex.value]?.PlanList||[]) as Task[])
const roomNames:Record<string,string>={control:'控制中枢',manufacture:'制造站',trading:'贸易站',power:'发电站',meeting:'会客室',hire:'办公室',dormitory:'宿舍',processing:'加工站',training:'训练室'}
const taskNames:Record<string,string>={StartUp:'开始唤醒与账号切换',DepotMaintain:'库存保持',Fight:'理智作战',Infrast:'基建换班',Recruit:'公开招募',Mall:'信用收支',Award:'领取奖励',UserDataUpdate:'更新数据',Roguelike:'集成战略',Custom:'自定义任务'}
const labels:Record<string,string>={IsEnable:'启用任务',AccountSwitchEnabled:'自动切换到该账号',UseMedicine:'使用普通理智药',MedicineCount:'普通药预算',UseStone:'使用源石',StoneCount:'源石预算',UseExpiringMedicine:'使用48小时内临期药',MedicineExpireDays:'临期药天数',StagePlan:'关卡列表',TimesLimit:'次数上限',EnableTimesLimit:'限制执行次数',Series:'连续作战次数',EnableTargetDrop:'限定目标掉落',DropId:'材料 ID',DropCount:'目标数量',IsInventoryTarget:'按库存目标判断',IsDrGrandet:'等待理智恢复',UseExpireMedicineForActivity:'活动期使用临期药',UseCustomAnnihilation:'自选剿灭',AnnihilationStage:'剿灭关卡',UseOptionalStage:'使用备选关卡',UpdateDepot:'运行前识别仓库',SkipDuringActivity:'活动期间跳过',SkipDuringResourceCollection:'资源收集关卡期间跳过',OnlyFirstInsufficientPlan:'只执行首个不足目标',SortByProgress:'按达成率排序',UseAutoSeries:'自动选择连战次数',DormTrustEnabled:'宿舍提升信赖',DormThreshold:'宿舍心情阈值（%）',OriginiumShardAutoReplenishment:'自动补货源石碎片',DormFilterNotStationed:'宿舍过滤未进驻干员',ReceptionMessageBoard:'留言板',ReceptionClueExchange:'线索交流',SendClue:'赠送线索',ContinueTraining:'继续训练',FiammettaRecoveryEnabled:'菲亚梅塔恢复',PlanSelect:'排班方案序号',UsesOfDrones:'无人机用途',MaxTimes:'最多招募次数',UseExpedited:'使用加急许可',PreferTagEnabled:'优先标签',PreserveTagEnabled:'保留标签',RefreshLevel3:'刷新三星标签',ForceRefresh:'强制刷新',Level3Choose:'选择三星',Level4Choose:'选择四星',Level5Choose:'选择五星',Level6Choose:'选择六星',ExtraTagMode:'额外标签模式',Level3RecruitmentPermitReserveEnabled:'保留三星招募许可',Level3RecruitmentPermitReserve:'保留许可数量',Level3Time:'三星招募时长（分钟）',Level4Time:'四星招募时长（分钟）',Level3PreferTags:'三星优先标签',PreserveTagList:'保留标签列表',Shopping:'购买信用商品',CreditFight:'信用作战',CreditFightOnceADay:'信用作战每日一次',CreditFightFormation:'信用作战编队',VisitFriends:'访问好友',VisitFriendsOnceADay:'访问好友每日一次',ShoppingIgnoreBlackListWhenFull:'信用溢出时忽略黑名单',OnlyBuyDiscount:'仅购买折扣商品',ReserveMaxCredit:'保留信用',FirstList:'优先购买列表',BlackList:'购买黑名单',Award:'领取任务奖励',Mail:'领取邮件',FreeGacha:'免费单抽',Orundum:'领取合成玉',Mining:'领取矿区奖励',SpecialAccess:'特别通行证',SignInEvent:'签到活动'}
const states:Record<string,string>={draft:'待确认',queued:'等待 Windows',waiting:'等待 MAA 空闲',dispatched:'Windows 正在处理',applied:'已保存并校验',cancelled:'已取消',conflict:'配置发生变化',blocked:'未应用',rejected:'校验未通过',unknown:'结果待核实',expired:'预览已过期'}
const enumLabels:Record<string,string>={_NotUse:'不使用',Money:'龙门币',SyntheticJade:'合成玉',CombatRecord:'作战记录',PureGold:'赤金',OriginStone:'源石',Chip:'芯片'}
function fields(t:Task){return catalog.value.tasks[t.TaskType]||{}}
function keys(t:Task){const f=fields(t);return [...(f.bool||[]),...Object.keys(f.int||{}),...Object.keys(f.enum||{}),...(f.string||[]),...(f.strings||[])].filter(k=>k in t)}
function missing(t:Task){const f=fields(t);return [...(f.bool||[]),...Object.keys(f.int||{}),...Object.keys(f.enum||{}),...(f.string||[]),...(f.strings||[])].filter(k=>!(k in t))}
function isBool(t:Task,k:string){return fields(t).bool?.includes(k)}
function fixed(k:string){return secondary.value&&['UseMedicine','UseStone','MedicineCount','StoneCount','MedicineExpireDays','UseExpiringMedicine'].includes(k)}
function addField(i:number){const k=addFields.value[i];if(!k)return;const t=tasks.value[i]!,f=fields(t);t[k]=f.bool?.includes(k)?false:f.int?.[k]?f.int[k]![0]:f.enum?.[k]?f.enum[k]![0]:f.strings?.includes(k)?[]:'';addFields.value[i]=''}
function parseList(value:string){return value.split(/[\n,，]+/).map(s=>s.trim()).filter(Boolean)}
function taskOperations():Op[]{const out:Op[]=[];tasks.value.forEach((t,i)=>{keys(t).forEach(k=>{if(!same(t[k],original.value[i]?.[k]))out.push({scope:'task',task:i,field:k,value:t[k]})});if(t.TaskType==='DepotMaintain')(t.PlanList||[]).forEach((p:Task,n:number)=>{for(const k of ['Stage','DropId','DropCount','UseMedicine','MedicineCount','UseStone','StoneCount'])if(k in p&&!same(p[k],original.value[i]?.PlanList?.[n]?.[k]))out.push({scope:'plan',task:i,plan:n,field:k,value:p[k]})})});return out}
function operations():Op[]{if(mode.value==='rooms'){const out:Op[]=[];(schedule.value?.plans||[]).forEach((p,s)=>Object.entries(p.rooms||{}).forEach(([room,items])=>items.forEach((v,n)=>{for(const field of ['operators','candidates','skip'] as const){if(!same(v[field],originalSchedule.value?.plans[s]?.rooms?.[room]?.[n]?.[field])&&v[field]!==undefined)out.push({scope:'schedule',shift:s,room,index:n,field,value:v[field]})}})));return out}if(mode.value==='timers'){const out:Op[]=[];timers.value.forEach((t,i)=>{for(const [field,k] of [['IsEnabled','enabled'],['Hour','hour'],['Minute','minute']])if(!same(t[k!],originalTimers.value[i]?.[k!]))out.push({scope:'timer',index:t.id,field,value:t[k!]})});return out}return taskOperations()}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function load(){if(!id.value)return;const a=props.demo?props.accounts.find(a=>a.id===id.value)!:await request<Account>(`/accounts/${id.value}/status`);snapshot.value=a;original.value=clone(a.profile?.editable||[]);tasks.value=clone(original.value);originalSchedule.value=a.profile?.schedule?clone(a.profile.schedule):null;schedule.value=clone(originalSchedule.value);timers.value=clone((a.instance?.native_timers||[]).filter(t=>t.profile_id===a.profile?.id));originalTimers.value=clone(timers.value);depotIndex.value=Math.max(0,tasks.value.findIndex(t=>t.TaskType==='DepotMaintain'));shift.value=0;emit('refresh')}
async function refreshPlans(){if(props.demo)return;try{plans.value=await request<Plan[]>('/config/plans');if(selectedPlan.value)selectedPlan.value=plans.value.find(p=>p.id===selectedPlan.value!.id)||selectedPlan.value}catch(e){error.value=(e as Error).message}}
async function preview(ops?:Op[],target?:string){await run(async()=>{if(props.demo){message.value='演示模式不修改实际配置。';return}const changes=ops||operations();if(!changes.length)throw Error('请先修改需要调整的选项');if(changes.length>64)throw Error('一次最多调整64个字段，请分批保存');selectedPlan.value=await request<Plan>(`/accounts/${id.value}/config/preview`,{method:'POST',body:JSON.stringify({target:target||(mode.value==='rooms'?'schedule':mode.value==='timers'?'timers':'config'),operations:changes,silent:!notifySave.value})});ack.value=false;await refreshPlans()})}
async function approve(){if(!selectedPlan.value||!ack.value)return;await run(async()=>{await request(`/config/plans/${selectedPlan.value!.id}/approve`,{method:'POST',body:JSON.stringify({confirm:selectedPlan.value!.id})});message.value='已保存到应用队列。Windows 在 MAA 空闲时关闭、备份、写入并重新载入。';await refreshPlans()})}
async function cancel(){if(!selectedPlan.value)return;await run(async()=>{await request(`/config/plans/${selectedPlan.value!.id}/cancel`,{method:'POST',body:'{}'});await refreshPlans()})}
async function rollback(p:Plan){await run(async()=>{selectedPlan.value=await request<Plan>(`/config/plans/${p.id}/rollback`,{method:'POST',body:'{}'});ack.value=false;await refreshPlans()})}
function structural(ops:Op[]){if(taskOperations().length){error.value='请先保存或刷新当前字段修改，再单独调整顺序或增删计划。';return}preview(ops,'config')}
function moveTask(i:number,delta:number){const order=tasks.value.map((_,n)=>n);[order[i],order[i+delta]]=[order[i+delta]!,order[i]!];structural([{scope:'order',value:order}])}
function movePlan(i:number,delta:number){const items=tasks.value[depotIndex.value]?.PlanList||[],order=items.map((_:unknown,n:number)=>n);[order[i],order[i+delta]]=[order[i+delta],order[i]];structural([{scope:'plan_order',task:depotIndex.value,value:order}])}
const display=(v:unknown)=>v===undefined||v===null?'未设置':typeof v==='boolean'?v?'开启':'关闭':typeof v==='object'?JSON.stringify(v):String(v)
let timer:ReturnType<typeof setInterval>
watch(id,()=>{selectedPlan.value=null;run(load)})
onMounted(async()=>{await run(async()=>{if(!props.demo)catalog.value=await request('/assistant/rules');await load();await refreshPlans()});timer=setInterval(refreshPlans,3000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template>
<div class="configuration-workspace">
<div class="config-top"><label>选择要修改的账号<select v-model="id"><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}} · {{a.profile?.name||'未绑定'}}</option></select></label><button class="button" :disabled="busy" @click="run(load)"><RefreshCw :size="16"/>重新读取</button><span class="muted">直接编辑，无需配置 AI 接口。</span></div>
<p class="inline-alert" role="alert" v-if="error">{{error}}</p><p class="agent-feedback" role="status" v-if="message"><Check :size="16"/>{{message}}</p>
<div class="info-strip" v-if="selected"><ShieldCheck :size="17"/><span>{{secondary?'副号保护：普通药0、源石0、临期药48小时。':'主号资源策略独立保存。'}} {{selected.instance?.process_running?'MAA 已打开，确认后会等待空闲并安全重载。':'MAA 已退出，可在确认差异后写入。'}}</span></div>
<div class="config-layout"><section class="panel config-fields"><div class="config-tabs"><button v-for="(label,key) in {tasks:'任务设置',depot:'库存计划',rooms:'基建排班',timers:'原有定时'}" :key="key" :class="{active:mode===key}" @click="mode=key">{{label}}</button></div>
<div v-if="mode==='tasks'" class="config-body"><p class="muted" v-if="!tasks.length">请先由管理员绑定已发现的 MAA 配置档。</p><details v-for="(t,i) in tasks" :key="i" :open="i===0" class="config-task"><summary><span>{{String(i+1).padStart(2,'0')}} · {{taskNames[t.TaskType]||t.TaskType}}</span><small>{{catalog.tasks[t.TaskType]?(t.IsEnable?'已启用':'未启用'):'此类型保留原设置'}}</small></summary><div class="config-order"><button class="button small" :disabled="busy||i<=1" @click="moveTask(i,-1)"><ArrowUp :size="14"/>上移</button><button class="button small" :disabled="busy||i===0||i===tasks.length-1" @click="moveTask(i,1)"><ArrowDown :size="14"/>下移</button></div><div class="config-field-grid"><label v-for="k in keys(t)" :key="k" :class="{'config-check':isBool(t,k)}"><template v-if="isBool(t,k)"><input type="checkbox" v-model="t[k]" :disabled="fixed(k)"/><span>{{labels[k]||k}}</span></template><template v-else>{{labels[k]||k}}<input v-if="fields(t).int?.[k]" type="number" v-model.number="t[k]" :min="fields(t).int![k]![0]" :max="fields(t).int![k]![1]" :disabled="fixed(k)"/><select v-else-if="fields(t).enum?.[k]" v-model="t[k]"><option v-for="v in fields(t).enum![k]" :value="v">{{enumLabels[v]||v}}</option></select><textarea v-else-if="fields(t).strings?.includes(k)" :value="(t[k]||[]).join('\n')" @input="t[k]=parseList(($event.target as HTMLTextAreaElement).value)" rows="3" placeholder="每行一项"></textarea><input v-else v-model="t[k]"/></template></label></div><div class="config-add-field" v-if="missing(t).length"><select v-model="addFields[i]"><option value="">添加其他可配置项…</option><option v-for="k in missing(t)" :value="k">{{labels[k]||k}}</option></select><button class="button small" :disabled="!addFields[i]" @click="addField(i)"><Plus :size="14"/>添加选项</button></div></details></div>
<div v-else-if="mode==='depot'" class="config-body"><label>库存保持任务<select v-model.number="depotIndex"><option v-for="(t,i) in tasks" v-show="t.TaskType==='DepotMaintain'" :key="i" :value="i" :disabled="t.TaskType!=='DepotMaintain'">{{i+1}} · {{taskNames[t.TaskType]||t.TaskType}}</option></select></label><p class="muted">材料使用游戏内 ID。当前库存尚未核实账号归属，目标数量会直接写入现有库存保持计划。</p><div class="config-plan-row" v-for="(p,n) in depotPlans" :key="n"><div class="config-field-grid"><label>材料 ID<input v-model="p.DropId"/></label><label>关卡<input v-model="p.Stage"/></label><label>目标数量<input type="number" min="0" max="1000000" v-model.number="p.DropCount"/></label></div><details v-if="!secondary"><summary>单项资源预算</summary><div class="config-field-grid"><label class="config-check"><input type="checkbox" v-model="p.UseMedicine"/>使用普通药</label><label>药剂数量<input type="number" min="0" max="999" v-model.number="p.MedicineCount"/></label><label class="config-check"><input type="checkbox" v-model="p.UseStone"/>使用源石</label><label>源石数量<input type="number" min="0" max="99" v-model.number="p.StoneCount"/></label></div></details><div class="agent-button-row"><button class="button small" :disabled="n===0||busy" @click="movePlan(n,-1)"><ArrowUp :size="14"/>上移</button><button class="button small" :disabled="n===tasks[depotIndex].PlanList.length-1||busy" @click="movePlan(n,1)"><ArrowDown :size="14"/>下移</button><button class="text-button" :disabled="busy" @click="structural([{scope:'plan_remove',task:depotIndex,plan:n}])"><Trash2 :size="14"/>预览删除</button></div></div><section class="config-plan-row"><h3>添加库存目标</h3><div class="config-field-grid"><label>材料 ID<input v-model="newPlan.DropId" placeholder="例如 30012"/></label><label>关卡<input v-model="newPlan.Stage" placeholder="例如 1-7"/></label><label>目标数量<input type="number" min="1" max="1000000" v-model.number="newPlan.DropCount"/></label></div><button class="button" :disabled="busy||!newPlan.DropId||!newPlan.Stage" @click="structural([{scope:'plan_add',task:depotIndex,value:{...newPlan,UseMedicine:false,UseStone:false,MedicineCount:0,StoneCount:0}}])"><Plus :size="15"/>预览新增目标</button></section></div>
<div v-else-if="mode==='rooms'" class="config-body"><p class="muted" v-if="!schedule">此账号未读取到独立基建排班文件。</p><template v-else><label>班次<select v-model.number="shift"><option v-for="(p,i) in schedule.plans" :value="i">{{p.name||`第${i+1}班`}}</option></select></label><div v-for="(items,room) in schedule.plans[shift]?.rooms" :key="room"><section class="config-plan-row" v-for="(v,n) in items" :key="n"><h3>{{roomNames[room]||room}} {{n+1}}</h3><label>干员（每行一位）<textarea :value="(v.operators||[]).join('\n')" @input="v.operators=parseList(($event.target as HTMLTextAreaElement).value)" rows="3"></textarea></label><label>候补干员<textarea :value="(v.candidates||[]).join('\n')" @input="v.candidates=parseList(($event.target as HTMLTextAreaElement).value)" rows="2"></textarea></label><label class="config-check"><input type="checkbox" v-model="v.skip"/>跳过此房间</label></section></div></template></div>
<div v-else class="config-body"><p class="muted">这些是 MAA 已有的定时，继续由 MAA 执行。调整前会显示差异；只可修改本账号项目。网页新增每日/每周计划请到「任务计划」。</p><section class="config-plan-row" v-for="t in timers" :key="t.id"><div class="config-field-grid"><label class="config-check"><input type="checkbox" v-model="t.enabled"/>启用原有定时 {{t.id+1}}</label><label>小时<input type="number" min="0" max="23" v-model.number="t.hour"/></label><label>分钟<input type="number" min="0" max="59" v-model.number="t.minute"/></label></div></section><p v-if="!timers.length" class="muted">当前账号没有分配到原有 MAA 定时项，可在任务计划中新增。</p></div>
<div class="config-save"><label class="config-check"><input type="checkbox" v-model="notifySave"/>保存结果推送通知</label><button class="button primary" :disabled="busy||!selected?.bound" @click="preview()"><Save :size="16"/>预览并保存修改<ArrowRight :size="16"/></button><span class="muted">核对差异后确认，保留其他配置。</span></div></section>
<aside class="panel config-review"><div class="panel-heading"><div><span class="eyebrow">// REVIEW & SAVE</span><h2>本次修改</h2></div><ShieldCheck :size="20"/></div><div class="config-body"><p class="muted" v-if="!selectedPlan">修改左侧字段后，点击「预览并保存修改」。这里会显示每一项原值和新值。</p><template v-else><span class="agent-chip">{{states[selectedPlan.state]||selectedPlan.state}}</span><p class="muted">{{selectedPlan.target==='schedule'?'基建排班':selectedPlan.target==='timers'?'原有定时':'任务配置'}}</p><div class="config-diff" v-for="d in selectedPlan.diff" :key="d.path"><code>{{d.path}}</code><span>{{display(d.before)}}</span><ArrowDown :size="15"/><strong>{{display(d.after)}}</strong></div><template v-if="selectedPlan.state==='draft'"><label class="config-check"><input type="checkbox" v-model="ack"/>已核对账号与以上差异</label><button class="button primary wide" :disabled="busy||!ack" @click="approve"><Check :size="16"/>确认保存并重载</button></template><p v-if="selectedPlan.receipt" class="info-strip">{{selectedPlan.receipt}}</p><button v-if="['draft','queued','waiting'].includes(selectedPlan.state)" class="text-button" :disabled="busy" @click="cancel">取消此次修改</button><button v-if="selectedPlan.state==='applied'" class="button" :disabled="busy" @click="run(load)"><RefreshCw :size="15"/>读取保存后的配置</button></template><h3 class="config-history-title">此账号的修改记录</h3><div v-for="p in plans.filter(p=>p.account_id===id).slice(0,10)" :key="p.id" class="config-history"><button class="text-button" @click="selectedPlan=p;ack=false">{{states[p.state]||p.state}} · {{new Date(p.expires_at).toLocaleTimeString()}}</button><button v-if="p.state==='applied'&&!p.rollback_of" class="text-button" :disabled="busy" @click="rollback(p)"><Undo2 :size="13"/>预览回滚</button></div></div></aside></div>
</div>
</template>
<style scoped>
